using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends debug information for a call to Telegram servers
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SendCallDebugInformationAsync(InputCall callId = default, string debugInformation = default)
    {

           using var activity =  StartCallActivity("SendCallDebugInformationAsync", typeof(SendCallDebugInformation).FullName ?? "SendCallDebugInformationAsync");

           try
           {
             return client.SendCallDebugInformationAsync(callId, debugInformation);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
